function StarlinkCanvas() {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (!ctx) return;

        let animationFrameId: number;
        const width = 1600;
        const height = 1600;

        // Reduced from 420 → 280 nodes: still dense but cheaper O(n²) startup
        const numNodes = 280;
        const nodes: { x: number; y: number; radius: number }[] = [];
        for (let i = 0; i < numNodes; i++) {
            nodes.push({
                x: 450 + Math.random() * 600,
                y: 200 + Math.random() * 1200,
                radius: Math.random() * 1.5 + 0.5,
            });
        }

        // Pre-compute connections — cache alpha so we don't recalculate per frame
        const connections: { n1: any; n2: any; alpha: number }[] = [];
        for (let i = 0; i < nodes.length; i++) {
            for (let j = i + 1; j < nodes.length; j++) {
                const dx = nodes[i].x - nodes[j].x;
                const dy = nodes[i].y - nodes[j].y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < 100) {
                    connections.push({ n1: nodes[i], n2: nodes[j], alpha: (1 - dist / 100) * 0.3 });
                }
            }
        }

        // Pre-build clip Path2D once — avoid re-parsing the giant SVG string every frame
        let clipPath2D: Path2D | null = null;
        let clipOffsetX = 0;
        let clipOffsetY = 0;
        if (KERALA_PATHS.length > 0) {
            const p = KERALA_PATHS[0];
            clipPath2D = new Path2D(p.d);
            clipOffsetX = parseFloat(p.x);
            clipOffsetY = parseFloat(p.y);
        }

        // Reduced from 40 → 22 glows
        const activeGlows: { conn: any; progress: number; speed: number }[] = [];
        const numGlows = 22;
        for (let i = 0; i < numGlows; i++) {
            activeGlows.push({
                conn: connections[Math.floor(Math.random() * connections.length)],
                progress: Math.random(),
                speed: 0.005 + Math.random() * 0.015,
            });
        }

        const render = () => {
            ctx.clearRect(0, 0, width, height);
            ctx.save();

            // Apply cached clip path
            if (clipPath2D) {
                ctx.translate(clipOffsetX, clipOffsetY);
                ctx.clip(clipPath2D);
                ctx.translate(-clipOffsetX, -clipOffsetY);
            }

            // --- Batch all connection lines in ONE path per alpha bucket would be ideal,
            //     but since alphas vary continuously we at least avoid redundant state changes
            //     by not touching fillStyle between strokes. ---
            ctx.lineWidth = 1.0;
            for (const c of connections) {
                ctx.beginPath();
                ctx.strokeStyle = `rgba(255,255,255,${c.alpha.toFixed(3)})`;
                ctx.moveTo(c.n1.x, c.n1.y);
                ctx.lineTo(c.n2.x, c.n2.y);
                ctx.stroke();
            }

            // Draw nodes — one fillStyle set, batched with individual beginPath/fill
            ctx.fillStyle = "rgba(255,255,255,0.8)";
            for (const node of nodes) {
                ctx.beginPath();
                ctx.arc(node.x, node.y, node.radius, 0, Math.PI * 2);
                ctx.fill();
            }

            // Draw traveling glows — NO shadowBlur (huge perf cost).
            // Instead, draw a cheap radial gradient that mimics a soft glow.
            for (const glow of activeGlows) {
                glow.progress += glow.speed;
                if (glow.progress >= 1) {
                    glow.progress = 0;
                    glow.conn = connections[Math.floor(Math.random() * connections.length)];
                }

                const gx = glow.conn.n1.x + (glow.conn.n2.x - glow.conn.n1.x) * glow.progress;
                const gy = glow.conn.n1.y + (glow.conn.n2.y - glow.conn.n1.y) * glow.progress;

                // Radial gradient glow — cheap, no GPU blur pass required
                const grad = ctx.createRadialGradient(gx, gy, 0, gx, gy, 10);
                grad.addColorStop(0, "rgba(255,255,255,0.95)");
                grad.addColorStop(0.4, "rgba(255,255,255,0.35)");
                grad.addColorStop(1, "rgba(255,255,255,0)");
                ctx.beginPath();
                ctx.fillStyle = grad;
                ctx.arc(gx, gy, 10, 0, Math.PI * 2);
                ctx.fill();

                // Bright core dot on top
                ctx.beginPath();
                ctx.fillStyle = "rgba(255,255,255,1)";
                ctx.arc(gx, gy, 2, 0, Math.PI * 2);
                ctx.fill();
            }

            ctx.restore();
            animationFrameId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return <canvas ref={canvasRef} width={1600} height={1600} style={{ width: "100%", height: "100%" }} />;
}

